#!/data/data/com.termux/files/usr/bin/bash
# ============================================
# Kindle WiFi 传书 — Termux 快速启动脚本
# ============================================
# 用法:
#   1. 在 Termux 中运行: bash termux-run.sh
#   2. 记下显示的地址
#   3. 在 Kindle 浏览器打开该地址
# ============================================

set -e

# 检查 Python 3
if ! command -v python3 &>/dev/null; then
    echo "[*] 正在安装 Python 3 ..."
    pkg update -y && pkg install python3 -y
fi

# 创建工作目录
mkdir -p ~/kindle-server
cd ~/kindle-server

# 写入服务器脚本
echo "[*] 正在解压服务器脚本..."
python3 -c "
import base64, os
data = ''
with open('server.py', 'w') as f:
    f.write(base64.b64decode(data).decode('utf-8'))
"

# 创建书籍目录
mkdir -p books

echo ""
python3 server.py
